transforms.result:
::-webkit-scrollbar {
  width: 10px;
}

/* Track */
::-webkit-scrollbar-track {
  background: var(--scrollbar-track-color); 
  border-radius: 4px;
}
 
/* Handle */
::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb-color); 
  border-radius: 4px;
}

/* Handle on hover */
::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover-color);
}
.default-layout {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  color: var(--main-text-color);

}

.header {
  &__inner {
    display: flex;
    position: relative;
  justify-content: center;
  padding-top: 1rem;
  padding-bottom: 1rem;
  height: 80px;

  color: var(--secondary-text-color);
  }
  &__text {
    transition: color ease 1s 1s;
  }
  &__switch {
    display: block;
    position: absolute;
    left: 1rem;
    top: 1rem;
    z-index: 3;

  }

  &__switch-input {
    width: 0;
    height: 0;
    appearance: none;
    opacity: 0;
  }
  &__svg {
    width: 48px;
    height: auto;
    cursor: pointer;
    border-radius: 50%;
    box-shadow: 0px 0px 24px 12px #ffffff99;
    z-index: 5;

  }

}
.main {
  flex: 1 1 auto;
  min-height: calc(100svh - 160px);
  transition: background-color ease 1s 1s;
}
.footer {
  &__inner {
    display: flex;
  justify-content: center;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding-top: 1rem;
  padding-bottom: 1rem;
  height: 80px;
  background-color: var(--footer-background-color);
  color: var(--secondary-text-color);
  transition: color, background-color ease 0.5s 0.5s;
  }
}

.rotate-enter-active {
  animation: from-left linear 1s;
}
.rotate-leave-active {
  animation: from-left  linear 1s reverse;
}
.back-enter-active {
  animation: night-day linear 0.5s;
}
.back-leave-active {
  animation: night-day  linear 1s;
}
@keyframes translate-in {
  0% {
    transform: translateX(5000%);
  }
  100% {
    transform: translateX(0);
  }
}
@keyframes translate-out {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(5000%);
  }
}
@keyframes from-left {
  0% {
    transform: translateX(-200%);
  }
  100% {
    transform: translateX(0);
  }
}

@keyframes day-night {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(0);
  }
}
@keyframes night-day {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(100%);
  }
}
.dark-theme {
  --myColor1: #1e2499dd;
  --myColor2: #00044299;
  --myColor3: #00033633;
  --myColor4: #01032b22;
    background: linear-gradient(to right bottom, var(--myColor1), var(--myColor2),var(--myColor3),var(--myColor4)), url('../assets/svg/starry-night.svg');
  transition: --myColor1 2s 0.5s, --myColor2 2s 0.5s, --myColor3 2s 0.5s, --myColor4 2s 0.5s;
  animation: translate-out  linear 1s;
}

.light-theme {
  background: linear-gradient(to right bottom, var(--myColor1), var(--myColor2),var(--myColor3),var(--myColor4)), url('../assets/svg/starry-night.svg');
  transition: --myColor1 2s 0.5s, --myColor2 2s 0.5s , --myColor3 2s 0.5s, --myColor4 2s 0.5s;
  animation: translate-out  linear 1s;
}
.stars-svg {
  position: fixed;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  bottom: 0;
  right: 0;
  z-index: 0;
  opacity: 0;
  &__day {
    opacity: 0;
  }
  &__night {
    opacity: 1;
  }
}
